:none!important;transform:translateX(-50%);transition:transform .25s,opacity .25s}.imm4-hero__scroll:hover{opacity:.72;transform:translate(-50%,4px)}.imm4-hero__scroll span{display:block;width:13px;height:13px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(45deg) translate(-2px,-2px)}.imm4-facts-wrap{background:var(--imm4-cream-2);border-bottom:1px solid var(--imm4-hair)}.imm4-facts{display:grid;grid-template-columns:repeat(3,1fr);background:var(--imm4-cream-2)}.imm4-fact{padding:28px clamp(18px,4vw,54px);border-right:1px solid var(--imm4-hair)}.imm4-fact:last-child{border:0}.imm4-fact__label{display:flex;align-items:center;gap:7px;margin-bottom:7px;color:var(--imm4-soft);font-size:16px}.imm4-fact__icon{flex:none;font-family:"Material Symbols Outlined";font-size:16px;font-style:normal;font-weight:400;line-height:1;font-feature-settings:"liga";font-variation-settings:"FILL" 0,"wght" 400,"GRAD" 0,"opsz" 16}.imm4-fact strong{color:var(--imm4-navy);font:500 clamp(18px,2vw,28px)/1.25 "Noto Serif",serif}
