tent:"";position:absolute;right:0;bottom:0;left:0;height:1px;background:linear-gradient(90deg,#d4a04d 0 42%,transparent 75%)}.imm4-proof p{margin-bottom:0}.imm4-dossier{position:relative;padding:32px 46px 32px;border:3px solid #d2a252;background:radial-gradient(circle at 50% 7%,rgba(30,73,106,.48),transparent 34%),linear-gradient(145deg,#09263d 0%,#102e46 48%,#0a263d 100%);color:#fff;box-shadow:0 20px 38px rgba(45,35,24,.18),inset 0 0 0 2px rgba(255,255,255,.09),inset 0 0 32px rgba(4,22,36,.22)}.imm4-dossier:before{content:"account_balance";display:block;width:82px;margin:0 auto 12px;padding:10px 0 8px;border-top:2px solid #d9a855;border-bottom:2px solid rgba(217,168,85,.72);border-radius:50% 50% 0 0;color:#e1ad55;font-family:"Material Symbols Outlined";font-size:45px;font-weight:300;line-height:.82;text-align:center;font-feature-settings:"liga";font-variation-settings:"FILL" 0,"wght" 300,"GRAD" 0,"opsz" 48}.imm4-dossier h3{position:relative;margin:0 0 24px;padding:0 0 26px;color:#fff;font-size:25px;font-weight:500;line-height:1.12;text-align:center}.imm4-dossier h3:before{content:"";position:absolute;top:auto;bottom:0;left:50%;z-index:1;display:block;width:15px;height:15px;border-radius:3px;background:linear-gradient(138deg,#f8e7bd 0,#dcae5d 48%,#b8873c 100%);box-shadow:0 0 12px rgba(226,175,88,.32);transform:translate(-50%,50%) rotate(45deg)}.imm4-dossier h3:after{content:"";position:absolute;right:0;bottom:0;left:0;height:1px;border-top:0;background:linear-gradient(90deg,rgba(214,168,86,0) 0,rgba(214,168,86,.45) 32%,#e7c286 100%) 0 100%/calc(50% - 19px) 1px no-repeat,linear-gradient(270deg,rgba(214,168,86,0) 0,rgba(214,168,86,.45) 32%,#e7c286 100%) 100% 100%/calc(50% - 19px) 1px no-repeat}.imm4-dossier dl{display:grid;grid-template-columns:.56fr 1.4fr;gap:0;margin:0}.imm4-dossier dt,.imm4-dossier dd{display:flex;align-items:flex-start;padding:12px 10px;border-bottom:2px solid rgba(255,255,255,.2)}.imm4-dossier dt{color:rgba(255,255,255,.7);font-size:16px;font-wei