fter{content:"";position:absolute;top:52px;bottom:5px;left:22px;width:1px;background:var(--imm4-hair)}.imm4-route__step h3{margin-bottom:8px;font-size:23px}.imm4-route__step p{margin:0;color:var(--imm4-soft)}.imm4-clarity{position:relative;padding:2px 0 0 26px;border-left:3px solid var(--imm4-red);background:0 0;color:var(--imm4-soft);text-align:left}.imm4-clarity p{max-width:74ch;margin:0;color:var(--imm4-soft);font-family:"Noto Serif",Georgia,serif;font-size:clamp(16px,1.35vw,18px);font-style:italic;font-weight:400;line-height:1.62}.imm4-clarity strong{color:var(--imm4-navy);font-weight:500}@media(max-width:640px){#lo-trinh .imm4-route-quote{padding:22px 20px 22px 28px;font-size:17px;line-height:1.58}#lo-trinh .imm4-route-quote:before{top:-7px;left:8px;font-size:64px}.imm4-clarity{margin-left:30px;padding-left:18px}}
