</main>

<!-- ===== LIGHTBOX ===== -->
<div class="imm4-lightbox" role="dialog" aria-modal="true" aria-label="View the Konia Green photo and video gallery">
<button type="button" class="imm4-icon-btn" data-imm4-close aria-label="Close">&times;</button>
<button type="button" class="imm4-lightbox__nav imm4-lightbox__prev" data-imm4-prev aria-label="Previous media"><span class="material-symbols-outlined" aria-hidden="true">chevron_left</span></button>
<div class="imm4-lightbox__stage"></div>
<button type="button" class="imm4-lightbox__nav imm4-lightbox__next" data-imm4-next aria-label="Next media"><span class="material-symbols-outlined" aria-hidden="true">chevron_right</span></button>
<span class="imm4-lightbox__count" aria-live="polite"></span>
</div>
</div>
<script>
(function(){'use strict';var page=document.querySelector('.imm4');if(!page)return;var groups=[['.imm4-route__steps','.imm4-route__step'],['.imm4-dev__gallery','.imm4-dev__shot'],['.imm4-gallery','.imm4-gallery figure'],['.imm4-rights','.imm4-right'],['.imm4-timeline','.imm4-milestone'],['.imm4-faq','.imm4-faq details']];groups.forEach(function(group){var parent=page.querySelector(group[0]);if(!parent)return;parent.classList.remove('imm4-reveal','is-visible');parent.querySelectorAll(group[1]).forEach(function(item,index){item.classList.add('imm4-reveal');if(index%4)item.classList.add('imm4-reveal--delay-'+Math.min(index%4,3))})});page.querySelectorAll('.imm4-section .imm4-title,.imm4-gallery-note,.imm4-progress-note,.imm4-map__meta,.imm4-rights__intro').forEach(function(item){if(!item.closest('.imm4-reveal'))item.classList.add('imm4-reveal')})})();
</script>

<script>
(function(){'use strict';var hero=document.querySelector('.imm4-hero');if(!hero||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;var slides=Array.prototype.slice.call(hero.querySelectorAll('.imm4-hero__slide'));if(slides.length<2)return;var current=Math.max(0,slides.findIndex(function(slide){return slide.classList.contains('is-active')}));function nextSlide(){slides[current].classList.remove('is-active');current=(current+1)%slides.length;slides[current].classList.add('is-active')}var timer=null;function start(){if(timer===null)timer=window.setInterval(nextSlide,6000)}function stop(){if(timer!==null){window.clearInterval(timer);timer=null}}document.addEventListener('visibilitychange',function(){document.hidden?stop():start()});start()})();
</script>

<script>
(function(){
	'use strict';
	var page=document.querySelector('.imm4');if(!page)return;
	var siteHeader=document.getElementById('header'),siteBreadcrumb=document.querySelector('.header__bottom');
	if(siteBreadcrumb)siteBreadcrumb.style.display='none';
	function syncHeaderHeight(){if(siteHeader)document.documentElement.style.setProperty('--imm4-site-header-height',siteHeader.getBoundingClientRect().height+'px')}
	syncHeaderHeight();if(siteHeader&&'ResizeObserver'in window)new ResizeObserver(syncHeaderHeight).observe(siteHeader);
	var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
	page.querySelectorAll('a[href^="#"]').forEach(function(link){link.addEventListener('click',function(event){var target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();target.scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'})})});
	var lightbox=page.querySelector('.imm4-lightbox'),stage=lightbox.querySelector('.imm4-lightbox__stage'),count=lightbox.querySelector('.imm4-lightbox__count');
	var media=[].slice.call(page.querySelectorAll('#hinh-anh [data-imm4-media-type]')),mediaIndex=0,lastTrigger=null;
	var thumbGallery=page.querySelector('#hinh-anh .imm4-gallery__thumbs');if(thumbGallery){var thumbs=thumbGallery.querySelectorAll('figure');if(thumbs.length>4){var hiddenCount=thumbs.length-4,more=thumbs[3].querySelector('.imm4-gallery__more'),moreButton=thumbs[3].querySelector('button');thumbGallery.classList.add('has-more');if(more)more.textContent='+'+hiddenCount+' photos';if(moreButton)moreButton.setAttribute('aria-label','See more '+hiddenCount+' project images')}}
	function renderMedia(){var item=media[mediaIndex],type=item.dataset.imm4MediaType,src=item.dataset.imm4MediaSrc;stage.replaceChildren();if(type==='youtube'||type==='videopress'){var iframe=document.createElement('iframe');iframe.src=type==='youtube'?'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(src)+'?autoplay=1&rel=0':'https://videopress.com/embed/'+encodeURIComponent(src)+'?autoplay=1';iframe.title=item.getAttribute('aria-label')||'Project video';iframe.allow='autoplay; encrypted-media; picture-in-picture';iframe.allowFullscreen=true;stage.appendChild(iframe)}else{var image=document.createElement('img');image.src=src;image.alt=(item.querySelector('img')||{}).alt||'Project image';stage.appendChild(image)}count.textContent=(mediaIndex+1)+' / '+media.length}
	function openLightbox(index,trigger){mediaIndex=index;lastTrigger=trigger;renderMedia();lightbox.classList.add('is-open');document.body.style.overflow='hidden';lightbox.querySelector('[data-imm4-close]').focus()}
	function closeLightbox(){lightbox.classList.remove('is-open');stage.replaceChildren();document.body.style.overflow='';if(lastTrigger)lastTrigger.focus()}
	function moveMedia(step){mediaIndex=(mediaIndex+step+media.length)%media.length;renderMedia()}
	media.forEach(function(button,index){button.addEventListener('click',function(){openLightbox(index,button)})});
	lightbox.querySelector('[data-imm4-close]').addEventListener('click',closeLightbox);lightbox.querySelector('[data-imm4-prev]').addEventListener('click',function(){moveMedia(-1)});lightbox.querySelector('[data-imm4-next]').addEventListener('click',function(){moveMedia(1)});
	lightbox.addEventListener('click',function(event){if(event.target===lightbox)closeLightbox()});
	document.addEventListener('keydown',function(event){if(!lightbox.classList.contains('is-open'))return;if(event.key==='Escape')closeLightbox();if(event.key==='ArrowLeft')moveMedia(-1);if(event.key==='ArrowRight')moveMedia(1)});
	if('IntersectionObserver'in window&&!reduce){var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}})},{threshold:.1});page.querySelectorAll('.imm4-reveal').forEach(function(item){observer.observe(item)})}else{page.querySelectorAll('.imm4-reveal').forEach(function(item){item.classList.add('is-visible')})}
})();
</script>
